const a={id:"tisax_handbook",title:"TISAX Participant Handbook",version:"2.8",date:"2025-03-13",issuer:"ENX Association",language:"en",official_url:"https://portal.enx.com/en-us/TISAX/downloads/"},e=[{code:"AL1"},{code:"AL2"},{code:"AL3"}],o=[{id:1,name:"Info high",assessment_level:"AL2",isa_catalogues:["Information Security"]},{id:2,name:"Info very high",assessment_level:"AL3",isa_catalogues:["Information Security"]},{id:3,name:"Confidential",assessment_level:"AL2",isa_catalogues:["Information Security"]},{id:4,name:"Strictly confidential",assessment_level:"AL3",isa_catalogues:["Information Security"]},{id:5,name:"High availability",assessment_level:"AL2",isa_catalogues:["Information Security"]},{id:6,name:"Very high availability",assessment_level:"AL3",isa_catalogues:["Information Security"]},{id:7,name:"Proto parts",assessment_level:"AL3",isa_catalogues:["Prototype Protection"]},{id:8,name:"Proto vehicles",assessment_level:"AL3",isa_catalogues:["Prototype Protection"]},{id:9,name:"Test vehicles",assessment_level:"AL2",isa_catalogues:["Prototype Protection"]},{id:10,name:"Proto events",assessment_level:"AL2",isa_catalogues:["Prototype Protection"]},{id:11,name:"Data",assessment_level:"AL2",isa_catalogues:["Information Security","Data Protection"]},{id:12,name:"Special data",assessment_level:"AL3",isa_catalogues:["Information Security","Data Protection"]}],s=3,i=[{step:1,name:"Registration",summary_pt:"Registo do participante no portal ENX (sujeito a taxa): dados de contacto e faturação, aceitação dos termos e condições e definição do âmbito da avaliação (assessment scope), incluindo os objetivos de avaliação e as localizações."},{step:2,name:"Assessment",summary_pt:"Avaliação: preparação com base no catálogo ISA (autoavaliação), escolha de um audit provider TISAX, realização da(s) avaliação(ões) — no mínimo a avaliação inicial e, em caso de não conformidades, passos adicionais — e emissão do relatório oficial de avaliação TISAX com atribuição de etiquetas (labels) TISAX."},{step:3,name:"Exchange",summary_pt:"Partilha (Exchange): o participante partilha o resultado da avaliação com o(s) parceiro(s) através da plataforma de partilha, escolhendo o nível de acesso ao conteúdo do relatório. O resultado é válido por três anos, após os quais o processo de três passos tem de ser repetido."}],t="A Avaliação Simplificada de Grupo (Simplified Group Assessment, SGA) é uma opção facultativa para participantes TISAX com muitas localizações e um SGSI centralizado e altamente desenvolvido (a localização principal assegura o cumprimento das regras do SGSI em todas as localizações do âmbito, as localizações dependentes têm um canal fiável de retorno à principal e o seu feedback corresponde às expectativas definidas). Exige pelo menos três localizações no âmbito (recomendam-se pelo menos doze). Existem duas variantes: S-SGA (por amostragem), em que a localização principal é avaliada de forma mais aprofundada, um conjunto de localizações de amostra é verificado e as restantes são verificadas de forma menos aprofundada; e R-SGA (plano rotativo), em que as restantes localizações são verificadas com profundidade semelhante, distribuídas ao longo dos três anos de validade das etiquetas. A R-SGA não está disponível para os objetivos de proteção de protótipos. É necessário cumprir os requisitos adicionais para SGA definidos no ISA e passar uma verificação de pré-condições (extensão da avaliação inicial); só com todos os resultados positivos a SGA é aprovada. A publicação e partilha do resultado são iguais às do processo normal.",n={instrument:a,assessment_levels:e,assessment_objectives:o,label_validity_years:s,process_steps:i,sga_summary_pt:t};export{e as assessment_levels,o as assessment_objectives,n as default,a as instrument,s as label_validity_years,i as process_steps,t as sga_summary_pt};
